S.visits=S.visits||[];S.read=S.read||[];S.searches=S.searches||[];S.history=S.history||[];
const save=()=>localStorage.setItem(KEY,JSON.stringify(S));
function visit(k){if(!S.visits.includes(k))S.visits.push(k);const u=(location.pathname.split('/').pop()||'index.html')+(location.search||'');const h={u,t:(typeof titles!=='undefined'&&titles[page()])||'网页'};S.history=[h,...S.history.filter(x=>x.u!==u)].slice(0,8);save()}
function esc(x=''){return String(x).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function qs(k){return new URLSearchParams(location.search).get(k)}
function norm(x=''){return String(x).toLowerCase().normalize('NFKC').replace(/(\d{4})年0?(\d{1,2})月/g,(_,y,m)=>y+String(m).padStart(2,'0')).replace(/(\d{1,2})月(\d{1,2})[日号]?/g,(_,m,d)=>String(m).padStart(2,'0')+String(d).padStart(2,'0')).replace(/[^\p{L}\p{N}]+/gu,'')}
function queryTerms(q=''){const raw=String(q).trim(),parts=raw.split(/[\s,，、/]+/).filter(Boolean);return(parts.length?parts:[raw]).map(x=>D.searchAliases?.[x.toLowerCase()]||D.searchAliases?.[x]||x).map(norm).filter(Boolean)}
