function mailReader(i){const m=D.mail[i];return `<article class="mail-reader"><div class="reader-tools"><a href="index.html">← 收件箱</a><span>归档</span><span>举报</span><span>删除</span></div><h1>${esc(m.subject)}</h1><div class="sender-line"><span class="avatar">${esc(m.from.slice(0,1))}</span><div><b>${esc(m.from)}</b><small>发送给 周宁</small></div><time>${esc(m.date)}</time></div><div class="mail-copy"><p>${esc(m.body)}</p>${i===0?`<div class="mail-action-card"><div><b>安全确认已逾期</b><p>如仍无法确认旅行人安全，可由保单紧急联系人查看状态或发起境外协助。</p></div><a href="insurance.html?view=safety">查看安途安全确认 →</a></div>`:''}${i===1?`<div class="attachment-preview"><div class="pdf-page"><span>QIAN COASTAL</span><b>栖岸青年旅居 · 九日行程</b><p>ORDER / QA-0726-09</p><hr><small>DAY5 · 18:30 白潮酒店入住<br>21:30 拾味晚场（可选）</small></div><div><b>栖岸行程_最终版.pdf</b><p>PDF · 428 KB · 林沅共享</p><div class="row-actions"><a href="qian.html">打开项目官网</a><a href="qian-archive.html">订单中心</a></div></div></div>`:''}</div><div class="reply-box">回复 ${esc(m.from)}…</div></article>`}
