function qianHome(){const cards=D.qian.filter(x=>!['route','partners'].includes(x.id)).slice(0,9);return `<section class="travel-hero"><div class="travel-photo">${photo('qian','travel-hero-img')}<div class="travel-overlay"><span>SUMMER SESSION · 9 DAYS</span><h1>把九天留给海边</h1><p>旧城、摄影、海岸市场和一张不赶时间的餐桌。</p><a href="qian.html?view=route">查看九日路线</a></div></div><div class="travel-bookbox"><h2>夏末特别期</h2><div class="price"><b>¥4,980</b><span>/ 人</span></div><p>国际交通自理 · 8晚住宿 · 当地接驳 · 部分餐饮</p><dl><div><dt>出发</dt><dd>2026.08</dd></div><div><dt>人数</dt><dd>18—24</dd></div><div><dt>状态</dt><dd>本期已满</dd></div></dl><a href="qian.html?view=price">查看费用包含</a></div></section><section class="travel-intro"><div><span class="section-kicker">QIAN COASTAL RESIDENCY</span><h2>一段被安排得刚刚好的短暂停留</h2><p>栖岸是澄海国际文旅面向青年旅行者的九日海岸项目。报名页、合作酒店、保险与当地餐桌均可独立查询。</p></div><div class="travel-numbers"><div><b>09</b><span>天</span></div><div><b>03</b><span>合作服务</span></div><div><b>01</b><span>摄影工作坊</span></div></div></section><section class="travel-cards">${cards.map(x=>`<a href="qian.html?view=${x.id}"><span>${x.title}</span><p>${x.text}</p><em>了解更多 →</em></a>`).join('')}</section><section class="travel-route-tease"><div><span>DAY 01—09</span><h2>从抵达到返程</h2><p>当前官网将第五天列为“自由活动”。历史签约版本可通过订单中心核对。</p></div><a href="qian.html?view=route">查看完整路线</a></section>`}
function qianRoute(){const days=[['01','抵达与入住','机场接驳 · 开营说明 · 团体入住'],['02','旧城与夜市','步行导览 · 自由晚餐'],['03','城市摄影工作坊','街区观察 · 自由拍摄'],['04','海岸市场','上午市场 · 下午自由活动'],['05','自由活动','当前公开版本仅保留这一项'],['06','海崖拍摄','晨间拍摄 · 蓝线A接驳'],['07','当地餐桌','拾味餐桌 · 团体活动餐'],['08','自由创作','作品整理 · 自由安排'],['09','返程','统一送机 · 项目结束']];return `<div class="travel-page"><aside class="travel-side"><b>本期路线</b><span>夏末特别期</span><a href="qian-archive.html">订单与版本</a><a href="qian.html?view=transport">接驳说明</a></aside><section class="itinerary"><div class="travel-title"><span>ITINERARY</span><h1>九日路线</h1><p>实际时间可能因天气与当地活动调整，重大变化会保留在订单修订记录中。</p></div>${days.map(d=>`<article class="day-row ${d[0]==='05'?'day-change':''}"><div class="day-no">DAY ${d[0]}</div><div><h2>${d[1]}</h2><p>${d[2]}</p></div>${d[0]==='05'?'<span class="revision-badge">当前版本</span>':''}</article>`).join('')}</section></div>`}
function qianPartners(){return `<section class="partners-page"><div class="travel-title"><span>PARTNERS</span><h1>本期合作服务</h1><p>住宿、餐饮与保险均由独立机构提供，可直接访问合作方公开页面。</p></div><div class="partner-grid"><a href="hotel.html"><b>BAY TIDE</b><h2>白潮酒店</h2><p>团体入住、住客服务、房态与酒店后勤。</p><span>访问酒店官网 →</span></a><a href="restaurant.html"><b>SHIWEI TABLE</b><h2>拾味餐桌</h2><p>活动餐、晚场小桌与团体饮食偏好同步。</p><span>查看餐厅网站 →</span></a><a href="insurance.html"><b>ANTU TRAVEL CARE</b><h2>安途旅保</h2><p>独立保单、安全确认与境外紧急协助。</p><span>打开保单服务 →</span></a></div><div class="partner-note"><b>服务边界</b><p>合作方只接收履行本次服务所需的必要字段。旅行人安全确认由保险机构独立完成。</p></div></section>`}
function qianSupport(){visit('qian:support');const deep=S.deepConfirmed;return `<div class="support-console"><aside class="ticket-list"><div class="support-title"><b>栖岸服务中心</b><span>周宁 · 我的工单</span></div><button class="new-ticket">＋ 新建咨询</button><a class="ticket active"><span>行程中 · 进行中</span><b>无法联系团员 / 白潮酒店</b><small>工单 QN-260820-118</small></a><a class="ticket"><span>已结束</span><b>报名资料修改</b><small>08/14</small></a><div class="service-hours"><b>在线客服</b><p>08:00—23:30</p><span class="online-dot">在线</span></div></aside><section class="ticket-room"><header><div><span>工单 QN-260820-118</span><h1>无法联系团员 / 白潮酒店</h1></div><div class="ticket-state">等待核实</div></header><div class="ticket-context"><span><b>关联订单</b> QA-0726-09</span><span><b>出行期次</b> 夏末特别期</span><span><b>服务对象</b> 林沅</span></div><div class="chat-log"><div class="bubble me"><small>周宁 · 08:21</small><p>林沅从昨晚开始联系不上。她现在是否还在白潮？</p></div><div class="bubble agent"><small>栖岸客服 · 08:27</small><p>林女士因当地网络条件暂时无法取得联系，团队工作人员已确认本人状态正常。</p><span>客服编号 QN-27</span></div>${deep?`<div class="bubble agent alert-bubble"><small>栖岸客服 · 刚刚</small><p>周宁您好。请问您现在仍在查询林沅女士的行程吗？</p></div>`:''}</div><form class="support-compose" id="supportForm"><textarea required minlength="8" placeholder="写明需要项目方核实的时间、地点或订单情况"></textarea><div><span>可添加公开网页或订单编号</span><button>发送</button></div></form></section><aside class="ticket-detail"><h3>工单信息</h3><dl><div><dt>优先级</dt><dd>普通</dd></div><div><dt>渠道</dt><dd>网页客服</dd></div><div><dt>创建</dt><dd>08/20 08:21</dd></div><div><dt>最近更新</dt><dd>08:27</dd></div></dl><h3>服务快捷入口</h3><a href="qian-archive.html">我的订单</a><a href="qian.html?view=partners">合作服务</a><a href="qian.html?view=faq">常见问题</a><a href="qian.html?view=refund">退款与退出</a></aside></div>`}
function qianDetail(id){const x=D.qian.find(v=>v.id===id);if(!x)return qianHome();const rich=D.qianMore?.[id],rows=rich?.sections||qianExtras[id]||[[x.title,x.text]];const intro=rich?.intro||x.text;return `<div class="travel-content"><aside class="travel-menu"><b>出发前信息</b><a href="qian.html?view=about">关于栖岸</a><a href="qian.html?view=price">费用说明</a><a href="qian.html?view=insurance">保险说明</a><a href="qian.html?view=faq">常见问题</a><a href="qian.html?view=leader">领队介绍</a><a href="qian.html?view=transport">接驳</a><a href="qian.html?view=diet">饮食偏好</a><a href="qian.html?view=refund">退款规则</a><small>本页属于公开产品说明，具体签约内容以订单版本为准。</small></aside><article class="travel-article"><div class="travel-title"><span>QIAN COASTAL PROGRAM</span><h1>${esc(x.title)}</h1><p>${esc(intro)}</p></div><div class="info-specs">${rows.map(([a,b])=>`<div><h3>${esc(a)}</h3><p>${esc(b)}</p></div>`).join('')}</div>${id==='about'?`<section class="travel-factline"><div><b>运营</b><span>澄海国际文旅</span></div><div><b>形式</b><span>9日 / 8晚固定小团</span></div><div><b>人数</b><span>18—24人</span></div></section>`:''}${id==='price'?`<section class="price-breakdown"><b>特别期 ¥4,980</b><span>住宿 8晚</span><span>当地常规接驳</span><span>部分活动餐</span><span>指定期间保险</span><small>国际往返交通与自由活动个人消费自理。</small></section>`:''}${id==='faq'?`<div class="faq-note"><b>没有找到答案？</b><p>可使用页面顶部客服入口提交一般售后咨询；行程中安全问题仍应使用保险或当地正式援助渠道。</p></div>`:''}${id==='leader'?`<div class="testimonial"><b>往届旅友圈</b><blockquote>“耳机落车上，他晚上还帮我问到司机那里。”</blockquote><a href="forum.html?author=${encodeURIComponent('韩译')}">查看社区中提到韩译的公开发言</a></div>`:''}${id==='transport'?`<div class="route-box"><span>BLUE LINE A</span><b>常规团体接驳</b><p>机场 / 白潮酒店 / 主要活动点</p><small>特殊个人行程由工作人员另行协调。</small></div>`:''}</article></div>`}
function qian(){visit('qian:home');const v=qs('view')||'home';let content;if(v==='home')content=qianHome();else if(v==='route')content=qianRoute();else if(v==='partners')content=qianPartners();else if(v==='support')content=qianSupport();else content=qianDetail(v);shell(content);if(v==='support')$('#supportForm').onsubmit=e=>{e.preventDefault();const msg=$('#supportForm textarea').value.trim();if(msg.length<8){alert('请补充需要项目方核实的时间、地点或订单情况。');return}if(S.deepConfirmed){S.ending='return';save();location.href='ending.html'}else alert('留言已提交，工单状态更新为“等待核实”。')}}
function qianArchive(){visit('qian:archive');const code=qs('code')||'',ok=norm(code)===norm(D.order.code);shell(`<div class="account-shell"><aside><b>栖岸订单中心</b><a class="active">历史版本查询</a><a>订单资料</a><a>费用与退款</a><a>售后记录</a><hr><a href="qian.html">返回项目官网</a></aside><section class="account-main"><div class="account-title"><span>ORDER HISTORY</span><h1>历史签约版本查询</h1><p>用于售后争议、路线版本核对与签约内容留存。</p></div><form class="lookup-bar" id="orderForm"><label>项目订单号<input id="orderCode" value="${esc(code)}" placeholder="例如 QA-0000-00"></label><button>查询</button></form>${code&&!ok?'<div class="form-error">没有找到这个订单号，请核对格式。</div>':''}${ok?`<div class="order-card"><header><div><b>${D.order.code}</b><span>夏末特别期 · 已签约</span></div><em>版本差异</em></header><div class="compare"><section><small>签约版</small><h3>DAY 5</h3><p>${D.order.original}</p></section><section class="current-version"><small>当前官网</small><h3>DAY 5</h3><p>${D.order.current}</p></section></div><div class="revision-log"><b>修订记录</b><p>${D.order.revision}</p></div><div class="order-services"><div><span>住宿服务</span><b>白潮酒店</b></div><div><span>活动餐</span><b>拾味餐桌</b></div><div><span>常规接驳</span><b>蓝线A</b></div><div><span>保险</span><b>安途旅保</b></div></div></div>`:''}<div class="account-help"><b>为什么会保留历史版本？</b><p>签约后的路线、费用和合作服务若发生修改，订单中心仍会保留用户确认时的版本，用于售后核对。</p></div></section></div>`);$('#orderForm').onsubmit=e=>{e.preventDefault();location.href='qian-archive.html?code='+encodeURIComponent($('#orderCode').value)}}

function avatar(n){return `<span class="forum-avatar">${esc(n.slice(0,1))}</span>`}
function forum(){visit('forum:home');const id=qs('id'),tag=qs('tag'),author=qs('author');if(id){const p=D.forum.find(x=>x.id===id);if(!p){location.href='forum.html';return}if(!S.read.includes(id)){S.read.push(id);save()}visit('forum:'+id);const related=D.forum.filter(x=>x.id!==p.id&&x.tags.some(t=>p.tags.includes(t))).slice(0,4);shell(`<div class="forum-layout"><main class="thread-page"><div class="thread-breadcrumb"><a href="forum.html">旅友圈</a> / ${p.tags.map(t=>`<a href="forum.html?tag=${encodeURIComponent(t)}">${t}</a>`).join(' / ')}</div><article class="thread"><header>${avatar(p.author)}<div><h1>${esc(p.title)}</h1><p><a href="forum.html?author=${encodeURIComponent(p.author)}">${esc(p.author)}</a> · ${p.date} · ${p.tags.map(t=>`<span>${t}</span>`).join(' ')}</p></div></header><div class="thread-copy"><p>${esc(p.text)}</p>${p.image&&PHOTO[p.image]?`<div class="thread-photo">${photo(p.image,'thread-photo-img')}</div>`:''}</div><footer><span>收藏</span><span>分享</span><span>举报</span></footer></article><section class="replies"><h2>${p.comments.length} 条回复</h2>${p.comments.map((c,i)=>{const parts=c.split('：');return `<div class="reply">${avatar(parts[0])}<div><b>${esc(parts[0])}</b><p>${esc(parts.slice(1).join('：'))}</p><small>#${i+1}</small></div></div>`}).join('')}</section>${id==='f14'?`<div class="forum-link-card"><b>帖子中曾分享的链接</b><p>拾味旧版晚场排版页 · 主站改版后已无导航入口。</p><a href="restaurant.html?view=archive">打开旧链接</a></div>`:''}${id==='f15'?'<div class="forum-notice">该用户此后没有新的公开帖子。</div>':''}</main><aside class="forum-aside"><section><h3>作者</h3>${avatar(p.author)}<b>${esc(p.author)}</b><a href="forum.html?author=${encodeURIComponent(p.author)}">查看公开发言</a></section><section><h3>相关讨论</h3>${related.map(x=>`<a href="forum.html?id=${x.id}">${esc(x.title)}</a>`).join('')}</section></aside></div>`);return}
 let list=[...D.forum].sort((a,b)=>b.date.localeCompare(a.date));if(tag)list=list.filter(x=>x.tags.includes(tag));if(author)list=list.filter(x=>x.author===author||x.comments.some(c=>c.startsWith(author+'：')));const pg=Math.max(1,Number(qs('p')||1)),size=10,start=(pg-1)*size,items=list.slice(start,start+size);const hot=D.forum.slice(0,6);shell(`<div class="forum-home"><main><div class="feed-head"><div><h1>${author?esc(author)+' 的公开发言':tag?esc(tag)+' · 讨论':'旅友圈广场'}</h1><p>${author?'帖子与公开回复汇总。':'正在旅行的人、已经回来的人，和还在做攻略的人。'}</p></div><div class="feed-sort">最新发布 ▾</div></div><div class="forum-filter">${['全部','攻略','酒店','餐饮','返程','摄影','出发前'].map(t=>`<a class="${(!tag&&t==='全部')||tag===t?'active':''}" href="${t==='全部'?'forum.html':'forum.html?tag='+encodeURIComponent(t)}">${t}</a>`).join('')}</div><div class="feed-list">${items.map(p=>`<article class="feed-item ${S.read.includes(p.id)?'read':''}">${avatar(p.author)}<div class="feed-copy"><div class="feed-meta"><a href="forum.html?author=${encodeURIComponent(p.author)}">${esc(p.author)}</a><span>${p.date}</span></div><a class="feed-title" href="forum.html?id=${p.id}">${esc(p.title)}</a>${p.image&&PHOTO[p.image]?`<a class="feed-photo-link" href="forum.html?id=${p.id}">${photo(p.image,'feed-photo')}</a>`:''}<p>${esc(p.text)}</p><div class="feed-foot"><span>${p.tags.map(t=>'#'+t).join(' ')}</span><a href="forum.html?id=${p.id}">${p.comments.length} 回复</a></div></div></article>`).join('')}</div><div class="pagination">${pg>1?`<a href="forum.html?${tag?'tag='+encodeURIComponent(tag)+'&':''}${author?'author='+encodeURIComponent(author)+'&':''}p=${pg-1}">上一页</a>`:''}<span>第 ${pg} 页</span>${start+size<list.length?`<a href="forum.html?${tag?'tag='+encodeURIComponent(tag)+'&':''}${author?'author='+encodeURIComponent(author)+'&':''}p=${pg+1}">下一页</a>`:''}</div></main><aside class="forum-sidebar"><section><h3>社区正在讨论</h3>${hot.map((p,i)=>`<a href="forum.html?id=${p.id}"><em>${String(i+1).padStart(2,'0')}</em><span>${esc(p.title)}</span></a>`).join('')}</section><section><h3>常用标签</h3><div class="tag-cloud">攻略 酒店 摄影 夜市 晚场 返程 预算 独自旅行</div></section><section class="community-rule"><b>发帖前</b><p>请勿公开护照、保单号码或他人联系方式。</p></section></aside></div>`)}

function hotel(){visit('hotel:home');const v=qs('view')||'home',code=qs('code')||'';let body='';if(v==='home')body=`<section class="hotel-hero">${photo('hotel','hotel-hero-img')}<div class="hotel-hero-copy"><span>COAST DISTRICT · BAY TIDE</span><h1>住在海边，离城市也不远</h1><p>团体入住、短住与会议客房。</p><a href="hotel.html?view=service">查看客房与设施</a></div><form class="hotel-search"><label>入住<input value="08/18"></label><label>退房<input value="08/21"></label><label>住客<select><option>1间 · 1人</option></select></label><button type="button">查询房型</button></form></section><section class="hotel-intro"><div><span>BAY TIDE HOTEL</span><h2>白潮酒店</h2><p>海岸区的中型团体酒店，提供早餐、自助洗衣、行李寄存和独立夜间后勤服务。</p></div><dl><div><dt>前台</dt><dd>24小时</dd></div><div><dt>早餐</dt><dd>06:30—10:00</dd></div><div><dt>入住</dt><dd>15:00后</dd></div></dl></section><section class="hotel-services"><a href="hotel.html?view=service"><b>客房与设施</b><p>标准双床、泳池、洗衣与团体服务</p></a><a href="hotel.html?view=reviews"><b>住客评价</b><p>${D.hotelReviews.length}条近期公开短评</p></a><a href="hotel.html?view=group"><b>团体入住自助</b><p>使用项目订单号核对入住与退房摘要</p></a></section>`;
 if(v==='service')body=`<div class="hotel-page"><div class="hotel-page-title"><span>ROOMS & AMENITIES</span><h1>客房与设施</h1></div><section class="hotel-room-feature">${photo('pool','hotel-pool-img')}<div><h2>标准双床 · 团体房</h2><p>约22㎡，两张单人床、工作桌、独立卫浴。靠海房夜间可能听到道路声。</p><ul><li>Wi‑Fi覆盖客房与公共区域</li><li>二楼自助洗衣</li><li>早餐06:30开始</li><li>团体行李可统一寄存</li></ul></div></section><section class="amenity-grid"><div><b>前台服务</b><p>24小时入住、房卡、遗失物登记。</p></div><div><b>团体房务</b><p>集中入住、订单核对、房态摘要。</p></div><div><b>夜间后勤</b><p>布草、冷链与清运由独立后勤系统处理。</p></div><div><b>隐私</b><p>公开站不展示具体住客设备或个人证件信息。</p></div></section></div>`;
 if(v==='reviews'){const pg=Math.max(1,Number(qs('p')||1)),size=5,start=(pg-1)*size,rows=D.hotelReviews.slice(start,start+size);const avg=(D.hotelReviews.reduce((a,b)=>a+b.score,0)/D.hotelReviews.length).toFixed(1);body=`<div class="hotel-page"><div class="review-summary"><div><b>${avg}</b><span>/ 5.0</span><p>来自 ${D.hotelReviews.length} 条近期评价</p></div><div><span>位置</span><i style="width:89%"></i><span>清洁</span><i style="width:84%"></i><span>服务</span><i style="width:86%"></i></div></div><section class="hotel-review-list"><h1>住客评价</h1>${rows.map(r=>`<article><div><b>${esc(r.author)}</b><span>${r.date}</span></div><strong>${'★'.repeat(r.score)}${'☆'.repeat(5-r.score)}</strong><p>${esc(r.text)}</p></article>`).join('')}<div class="pagination">${pg>1?`<a href="hotel.html?view=reviews&p=${pg-1}">上一页</a>`:''}${start+size<D.hotelReviews.length?`<a href="hotel.html?view=reviews&p=${pg+1}">下一页</a>`:''}</div></section></div>`}
 if(v==='group'){const ok=code&&norm(code)===norm(D.hotel.groupCode);body=`<div class="hotel-portal"><aside><b>团体入住自助</b><a class="active">住宿状态</a><a>房卡与前台</a><a>遗失物</a><a href="hotel.html?view=privacy">隐私说明</a><small>仅显示团体服务必要信息</small></aside><section><div class="portal-title"><span>GROUP STAY</span><h1>查询团体住宿状态</h1></div><form id="hotelGroup" class="portal-search"><label>项目订单号<input id="hotelCode" value="${esc(code)}" placeholder="例如 QA-0000-00"></label><button>查询</button></form>${code&&!ok?'<div class="portal-error">未找到匹配的团体住宿记录。</div>':''}${ok?`<div class="stay-card"><header><div><b>订单 ${D.hotel.groupCode}</b><span>栖岸青年旅居</span></div><em class="stay-open">${D.hotel.publicStatus}</em></header><div class="stay-grid"><div><small>团体房</small><b>${D.hotel.room}</b></div><div><small>入住</small><b>${D.hotel.checkin}</b></div><div><small>正式退房</small><b>未记录</b></div></div><div class="stay-note"><b>前台摘要</b><p>${D.hotel.frontdeskNote}</p></div></div>`:''}<div class="portal-help"><b>查询范围</b><p>${D.hotel.groupHelp}</p></div></section></div>`}
 if(v==='privacy')body=`<div class="hotel-legal"><aside><b>住客服务</b><a class="active">隐私与网络</a><a href="hotel.html?view=group">团体订单</a><a href="hotel.html?view=supplier">供应商公示</a></aside><article><h1>住客隐私与网络说明</h1><p>${D.hotel.privacy}</p><h2>网络记录</h2><p>酒店公开站不会显示MAC地址、证件号码或具体设备身份。处于保险安全确认流程中的投递摘要，仅由获得授权的保险服务商向紧急联系人提供。</p><h2>团体房态</h2><p>项目订单查询只显示入住、正式退房和必要的前台状态摘要。</p><a class="hotel-text-link" href="insurance.html?view=safety">前往安途旅保安全确认 →</a></article></div>`;
 if(v==='supplier')body=`<div class="hotel-legal"><aside><b>酒店信息</b><a class="active">供应商公示</a><a href="hotel.html?view=annex">历史采购附件</a><a href="hotel.html?view=back">B2后勤说明</a></aside><article><h1>夜间后勤供应商公示</h1><p>${D.hotel.supplierPublic}</p><div class="vendor-card"><div><b>NIGHTPOST 区域团队</b><span>夜间后勤 / 冷链 / 布草运输</span></div><a href="nightpost.html">公开主页</a></div><h2>采购资料</h2><p>${D.hotel.supplierAnnex}</p><a class="hotel-text-link" href="hotel.html?view=annex">查看历史采购附件摘要 →</a></article></div>`;
 if(v==='annex')body=`<div class="document-center"><aside><b>文档中心</b><span>采购 / 历史附件</span><a href="hotel.html?view=supplier">← 返回供应商公示</a></aside><article class="document-paper"><header><span>BAY TIDE HOTEL</span><small>采购部 · 历史供应商摘要</small></header><h1>夜间后勤供应商历史摘要</h1><table><tr><th>供应商</th><td>NIGHTPOST 区域团队</td></tr><tr><th>合作编号</th><td><b>BTH-2407</b></td></tr><tr><th>结算方式</th><td>按月</td></tr><tr><th>具体账期</th><td>不在酒店摘要中展示</td></tr></table><p>本文件用于团体采购争议与历史结算核对。</p><footer>白潮酒店采购部 · 归档副本</footer></article></div>`;
 if(v==='back')body=`<div class="ops-page"><div class="ops-copy"><span>OPERATIONS / B2</span><h1>后勤通道说明</h1><p>${D.hotel.back}</p><dl><div><dt>住客权限</dt><dd>不开放</dd></div><div><dt>主要用途</dt><dd>布草 / 冷链 / 垃圾清运</dd></div><div><dt>夜间字段</dt><dd>B2-N / B2-L</dd></div></dl><p class="ops-note">普通前台只接收状态摘要，不显示夜间工单的客户自定义字段。</p></div>${photo('back','ops-photo')}</div>`;shell(body);if(v==='group')$('#hotelGroup').onsubmit=e=>{e.preventDefault();location.href='hotel.html?view=group&code='+encodeURIComponent($('#hotelCode').value)}}

function restaurant(){visit('food:home');const v=qs('view')||'home',code=qs('code')||'';if(v==='archive')visit('food:archive');let body='';if(v==='home')body=`<section class="food-hero"><div>${photo('food','food-hero-img')}<span class="food-caption">昼 · 今日餐桌</span></div><div class="food-hero-copy"><small>LOCAL TABLE · COAST DISTRICT</small><h1>把当天好吃的东西，认真做完</h1><p>午餐固定菜单，21:30后只留六张小桌。</p><a href="restaurant.html?view=menu">看今日菜单</a></div></section><section class="food-intro"><div><span>今日午餐</span><h2>${D.menus[0].items.join(' · ')}</h2><p>${D.menus[0].note}</p></div><a href="restaurant.html?view=booking">预约一张桌</a></section><section class="food-links"><a href="restaurant.html?view=night"><b>晚场小桌</b><span>21:30 / 仅六桌 / 随机菜单</span></a><a href="restaurant.html?view=history"><b>往期菜单</b><span>查看最近的公开出餐版本</span></a><a href="restaurant.html?view=comments"><b>食客留言</b><span>等位、余味席与真实吐槽</span></a></section>`;
 if(v==='menu'){const ms=[...D.menus].filter(m=>!m.archive).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);body=`<div class="menu-page"><div class="menu-cover"><span>MENU · ${ms[0].date}</span><h1>今日菜单</h1><p>午餐为固定出餐；实际供应会根据当日采购微调。</p></div><section class="menu-sheet"><h2>${ms[0].label}</h2>${ms[0].items.map((x,i)=>`<div class="menu-line"><span>${String(i+1).padStart(2,'0')}</span><b>${x}</b><em>${['主菜 / 当日柑橘与香草','汤 / 烤南瓜与海盐','主食 / 炭烤鸡腿','甜点 / 黄桃与奶冻'][i]||'当日菜品'}</em></div>`).join('')}<p class="menu-note">${ms[0].note}</p></section><section class="menu-recent"><h2>近期公开菜单</h2>${ms.slice(1).map(m=>`<a href="restaurant.html?view=history"><span>${m.date}</span><b>${m.items.join(' / ')}</b></a>`).join('')}</section></div>`}
 if(v==='history'){const arr=[...D.menus].filter(m=>!m.archive).sort((a,b)=>b.date.localeCompare(a.date)),pg=Math.max(1,Number(qs('p')||1)),size=6,start=(pg-1)*size;body=`<div class="menu-history"><header><span>PAST MENUS</span><h1>往期菜单</h1><p>公开出餐版本；员工排版与厨房预备页不在主站导航中。</p></header><div class="history-list">${arr.slice(start,start+size).map(m=>`<article><time>${m.date}</time><div><b>${m.label}</b><p>${m.items.join(' · ')}</p><small>${m.note}</small></div></article>`).join('')}</div><div class="pagination">${pg>1?`<a href="restaurant.html?view=history&p=${pg-1}">上一页</a>`:''}${start+size<arr.length?`<a href="restaurant.html?view=history&p=${pg+1}">下一页</a>`:''}</div></div>`}
 if(v==='night')body=`<section class="night-supper"><div class="night-copy"><small>LATE TABLE · 21:30</small><h1>晚场小桌</h1><p>六张桌，不公布固定菜单。厨师根据当天仍适合使用的食材调整小份菜，并遵循已登记过敏原。</p><div class="night-quote"><b>“余味席”</b><p>老客人对晚场随机菜单的旧称，不是单独套餐。</p></div><a href="restaurant.html?view=booking">查看今晚候位</a></div>${photo('supper','supper-photo')}</section>`;
 if(v==='booking')body=`<div class="booking-page"><section><small>RESERVATION</small><h1>订一张桌</h1><p>午餐可在线预约；21:30晚场只开放六桌，随机菜单不接受指定菜品。</p><form class="booking-form"><div><label>日期<input value="2026-08-20"></label><label>时间<select><option>19:00</option><option>19:30</option><option>20:00</option><option>21:30 晚场</option></select></label></div><div><label>人数<select><option>1位</option><option>2位</option></select></label><label>饮食偏好<input placeholder="例如：香草类不要"></label></div><label>联系邮箱<input placeholder="name@example.com"></label><button type="button" id="checkBooking">检查可预约时段</button></form></section><aside><b>今晚</b><p>普通晚餐仍有少量位置</p><hr><b>21:30 晚场</b><p>网上预约已截止，可电话询问候位。</p><small>随机菜单会遵循已登记过敏原。</small></aside></div>`;
 if(v==='group'){const ok=code&&norm(code)===norm(D.order.code);body=`<div class="food-group"><header><span>GROUP DINING</span><h1>团体用餐确认</h1><p>只显示项目订单同步的必要饮食字段，不显示姓名与联系方式。</p></header><form id="foodGroup"><label>项目订单号<input id="foodCode" value="${esc(code)}" placeholder="QA-0000-00"></label><button>查询</button></form>${code&&!ok?'<div class="food-error">未找到对应团体用餐记录。</div>':''}${ok?`<div class="diet-card"><span>${D.order.code}</span><b>已同步饮食备注</b><p>香草类不要</p><small>来自报名阶段的饮食偏好字段</small></div>`:''}</div>`}
 if(v==='comments'){const pg=Math.max(1,Number(qs('p')||1)),size=8,start=(pg-1)*size,rows=D.restaurantComments.slice(start,start+size);body=`<div class="food-comments"><header><span>GUEST BOOK</span><h1>食客留言</h1><p>普通公开留言，按发布时间倒序。</p></header><div>${rows.map((x,i)=>{const [a,...b]=x.split('|');return `<article><span>${String(start+i+1).padStart(2,'0')}</span><div><b>${esc(a)}</b><p>${esc(b.join(' '))}</p></div></article>`}).join('')}</div><div class="pagination">${pg>1?`<a href="restaurant.html?view=comments&p=${pg-1}">上一页</a>`:''}${start+size<D.restaurantComments.length?`<a href="restaurant.html?view=comments&p=${pg+1}">下一页</a>`:''}</div></div>`}
 if(v==='archive')body=`<div class="kitchen-archive"><aside><span>ARCHIVED PAGE</span><h1>晚场厨房预览</h1><p>旧版员工排版页。主站改版后已经没有导航入口。</p><a href="restaurant.html?view=history">返回公开菜单</a></aside><section><h2>旧排版菜单</h2>${D.menus.filter(m=>m.archive).map(m=>`<article><time>${m.date}</time><b>${m.items.join(' / ')}</b><p>${m.note}</p></article>`).join('')}<h2>厨房预备摘要</h2><table><thead><tr><th>日期</th><th>晚场席位</th><th>预备份数</th><th>后仓字段</th><th>结算抬头</th></tr></thead><tbody>${D.restaurantKitchen.map(r=>`<tr><td>${r.date}</td><td>${r.seats}</td><td>${r.prepared}</td><td>${r.batch}</td><td>${r.settlement}</td></tr>`).join('')}</tbody></table><p class="archive-foot">“B2-N”等为旧后仓批次字段，本页不解释来源。</p></section></div>`;shell(body);if(v==='group')$('#foodGroup').onsubmit=e=>{e.preventDefault();location.href='restaurant.html?view=group&code='+encodeURIComponent($('#foodCode').value)};if(v==='booking')$('#checkBooking').onclick=()=>alert('当日网上预约已截止，可电话询问候位。')}

function news(){visit('news:home');const id=qs('id'),v=qs('view'),sec=qs('section');if(v==='tip'){shell(`<div class="news-submit"><header><span>READER TIP</span><h1>向编辑部提交材料</h1><p>可匿名提交公开网页、文件链接与事件说明。编辑会优先处理能够复核具体页面、编号和时间的材料。</p></header><div class="news-submit-grid"><form id="tipForm"><label>主题<input id="tipSubject" required value="栖岸旅居相关材料"></label><label>材料说明<textarea id="tipNote" required minlength="20" placeholder="写明你看到的公开页面、编号、时间以及它们为什么互相矛盾"></textarea></label><label>公开链接或页面名<input id="tipLink" required placeholder="例如：NIGHTPOST 历史运单 / 海湾晨报缓存"></label><label>联系邮箱（可选）<input placeholder="用于编辑核实"></label><button>提交给编辑部</button><div id="tipMsg" class="form-feedback"></div></form><aside><b>提交说明</b><p>请勿上传护照、证件号码或非公开私人资料。</p><p>编辑部需要能独立打开或检索的公开来源；只有结论、没有来源编号的材料可能无法及时核实。</p></aside></div></div>`);$('#tipForm').onsubmit=e=>{e.preventDefault();const text=($('#tipSubject').value+' '+$('#tipNote').value+' '+$('#tipLink').value).trim();const hasRecord=/q7\s*[-－]?\s*b12/i.test(text),hasSource=/nightpost|夜邮/i.test(text),hasLink=/qa\s*[-－]?\s*0726\s*[-－]?\s*09|白潮|712|00:?20|换站/i.test(text);if(S.deepConfirmed&&hasRecord&&hasSource&&hasLink){S.ending='expose';save();location.href='ending.html'}else{$('#tipMsg').textContent=S.deepConfirmed?'材料已保存，但编辑部还无法把说明关联到具体公开记录。请补充运单编号、来源站点和至少一个可交叉核对的订单/地点/时间。':'材料已进入编辑部材料邮箱。'}};return}if(v==='attachment'){shell(`<div class="news-archive"><span>ATTACHMENT CACHE</span><h1>报道公开附件缓存</h1><p>来源：2026-06-21 商业报道 · “酒店夜间外包采购增加”</p><div class="attachment-file"><b>night_vendor_202608.pdf</b><dl><div><dt>合作商</dt><dd>NIGHTPOST</dd></div><div><dt>周期</dt><dd>2026-08</dd></div><div><dt>类别</dt><dd>酒店后勤外包</dd></div></dl></div><small>附件只说明采购与结算关系，不说明客户自定义业务字段。</small></div>`);return}if(id){const n=D.news.find(x=>x.id===id);if(!n){location.href='news.html';return}visit('news:'+id);const more=D.news.filter(x=>x.id!==id&&x.section===n.section).slice(0,4),paras=D.newsBodies?.[id]||[n.text];shell(`<div class="news-article-layout"><article class="news-article"><div class="news-path">首页 / ${n.section}</div><span class="news-section">${n.section}</span><h1>${esc(n.title)}</h1><div class="news-by"><span>${n.by||'海湾晨报编辑部'}</span><time>${n.date}</time></div><div class="article-share">分享 · 收藏 · 字号</div><p class="lead-copy">${esc(n.text)}</p><div class="news-body-copy">${paras.map((x,i)=>`<p${i===0?' class="first"':''}>${esc(x)}</p>`).join('')}</div>${id==='n08'?'<div class="retraction-box"><b>页面状态：已撤下</b><p>编辑记录显示，该页面曾在发布后37分钟被撤下；公开索引仅保留标题与摘要。</p></div>':''}${id==='n10'?'<div class="source-box"><b>公开附件</b><p>报道中引用的酒店后勤外包历史供应商摘要仍可从缓存访问。</p><a href="news.html?view=attachment">查看附件缓存</a></div>':''}<div class="news-fact-row"><span>栏目 ${esc(n.section)}</span><span>来源 公开报道 / 机构信息</span><span>更新 ${esc(n.date)}</span></div><footer>责任编辑：${n.by||'编辑部'} · 本文发布时间 ${n.date}</footer></article><aside class="news-related"><h3>同栏目</h3>${more.map(x=>`<a href="news.html?id=${x.id}"><span>${x.date}</span><b>${esc(x.title)}</b></a>`).join('')}</aside></div>`);return}
 let arr=[...D.news].sort((a,b)=>b.date.localeCompare(a.date));if(sec)arr=arr.filter(x=>x.section===sec);const pg=Math.max(1,Number(qs('p')||1)),size=9,start=(pg-1)*size,rows=arr.slice(start,start+size),lead=rows[0],secondary=rows.slice(1,4),rest=rows.slice(4);shell(`<div class="news-home"><section class="news-lead"><article><span>${lead?.section||''}</span><a href="news.html?id=${lead?.id||''}"><h1>${esc(lead?.title||'')}</h1></a><p>${esc(lead?.text||'')}</p><small>${lead?.date||''}</small></article><div>${secondary.map(n=>`<a href="news.html?id=${n.id}"><span>${n.section}</span><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p></a>`).join('')}</div></section><div class="news-divider"><b>${sec?esc(sec):'最新报道'}</b><span>LOCAL / TRAVEL / BUSINESS</span></div><section class="news-index">${rest.map(n=>`<a href="news.html?id=${n.id}"><time>${n.date}</time><span>${n.section}</span><div><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p></div></a>`).join('')}</section><div class="pagination">${pg>1?`<a href="news.html?${sec?'section='+encodeURIComponent(sec)+'&':''}p=${pg-1}">上一版</a>`:''}${start+size<arr.length?`<a href="news.html?${sec?'section='+encodeURIComponent(sec)+'&':''}p=${pg+1}">下一版</a>`:''}</div></div>`)}

function insurance(){visit('ins:home');const v=qs('view')||'home';if(v==='home'){shell(`<div class="ins-dashboard"><section class="policy-hero"><div><span>我的旅行保障</span><h1>境外旅行综合保障</h1><p>保单号 ${D.insurance.policy}</p><div class="policy-tags"><b>保障中</b><span>旅行人：${D.insurance.traveler}</span><span>第二紧急联系人：${D.insurance.contact}</span></div></div>${photo('flight','policy-photo')}</section><section class="ins-actions"><a href="insurance.html?view=safety"><span>安全确认</span><b>当前有1项逾期确认</b><em>查看状态 →</em></a><a href="insurance.html?view=case"><span>境外协助</span><b>${S.caseCreated?'协助单 AT-AID-0820':'报告失联 / 医疗 / 证件问题'}</b><em>进入协助中心 →</em></a><a href="insurance.html?view=help"><span>帮助中心</span><b>了解援助范围与材料</b><em>阅读说明 →</em></a></section><section class="policy-info"><h2>保单摘要</h2><dl><div><dt>保障期间</dt><dd>2026-08-14 — 2026-08-23</dd></div><div><dt>旅行地区</dt><dd>境外海岸区</dd></div><div><dt>旅行人</dt><dd>林沅</dd></div><div><dt>紧急联系人</dt><dd>周宁</dd></div></dl></section></div>`);return}
 if(v==='safety'){visit('ins:safety');shell(`<div class="safety-page"><header><span>SAFETY CHECK</span><h1>旅行人安全确认</h1><p>用于行程中定期确认已登记设备与本人状态。</p></header><div class="safety-status"><div class="status-mark">!</div><div><b>确认逾期</b><p>${D.insurance.safety}</p></div><span>需要关注</span></div><section class="safety-timeline"><h2>投递记录</h2><article><time>08/19 07:46</time><div><b>安全确认请求送达</b><p>已登记设备收到确认请求，未收到本人确认。</p></div></article><article class="latest"><time>08/19 22:11</time><div><b>再次送达</b><p>${D.insurance.gateway}</p></div></article></section><div class="safety-actions"><p>如果无法通过常用联系方式确认旅行人安全，可由紧急联系人发起境外协助。</p><a href="insurance.html?view=case">进入境外紧急协助</a></div></div>`);return}
 if(v==='help'){shell(`<div class="help-center"><aside><b>帮助中心</b><a class="active">境外紧急协助</a><a>安全确认</a><a>证件遗失</a><a>医疗与住院</a><a>理赔材料</a></aside><article><h1>境外紧急协助</h1><p>紧急联系人可报告失联、证件遗失、医疗协助等情况。请尽量提供最后已知地点、住宿信息与可核实的订单编号。</p><h2>提交后会发生什么</h2><ol><li>协助中心核实保单和紧急联系人权限。</li><li>根据所在地联系当地援助合作机构。</li><li>必要时转交正式公共安全渠道。</li></ol><h2>请避免提交</h2><p>未经授权的私人账号密码、非公开医疗记录或与事件无关的个人信息。</p></article></div>`);return}
 const deep=S.deepConfirmed,created=S.caseCreated;visit('ins:case');if(!created){shell(`<div class="case-center"><aside><b>境外协助中心</b><span class="active">新建协助请求</span><a href="insurance.html?view=help">协助说明</a><small>24小时境外援助</small></aside><section><header><span>NEW ASSISTANCE CASE</span><h1>报告无法联系旅行人</h1><p>该表单由保单紧急联系人提交，后续信息由人工协助中心核实。</p></header><form id="caseForm" class="case-form"><label>旅行人<input value="林沅" readonly></label><label>保单号<input value="${D.insurance.policy}" readonly></label><label>最后可以确认联系的时间<input required value="2026-08-18 21:16"></label><label>最后已知住宿<input value="白潮酒店"></label><label class="wide">情况说明<textarea required minlength="6">自DAY5开始无法联系，项目方称已确认本人安全；本人未按持续三年的入住报平安习惯更新共享相册。</textarea></label><div class="wide case-consent"><input type="checkbox" checked> 我确认以保单紧急联系人身份提交上述信息。</div><button class="wide">提交协助请求</button></form></section></div>`);$('#caseForm').onsubmit=e=>{e.preventDefault();S.caseCreated=true;save();location.reload()};return}
 shell(`<div class="case-center"><aside><b>境外协助中心</b><span class="active">AT-AID-0820</span><a href="insurance.html?view=help">协助说明</a><small>24小时境外援助</small></aside><section><header class="case-head"><div><span>CASE / AT-AID-0820</span><h1>旅行人无法联系</h1></div><em>已受理</em></header><div class="case-progress"><span class="done">请求提交</span><span class="active">补充位置</span><span>人工核验</span><span>当地协助</span></div><div class="case-note"><b>协助中心</b><p>请继续补充最后可以核实的位置与订单记录。网页材料将由人工核验。</p></div><form id="updateForm" class="case-form"><label>最后已知地点<input required id="aidPlace" value="白潮酒店" placeholder="尽量具体到房间 / 后勤区域"></label><label>相关订单或编号<input required id="aidRefs" value="QA-0726-09" placeholder="可填写多个公开编号"></label><label class="wide">补充说明<textarea required minlength="20" id="aidNote" placeholder="写明仍可核验的状态、时间与来源站点">${deep?'':'项目官网当前行程与签约版不一致；保险设备投递摘要仍指向白潮住客网关。'}</textarea></label><p class="wide case-helper">援助中心会按“地点—订单/编号—紧急时间”进行人工关联。请填写你已经从公开页面核实到的内容，不需要提交私人账号密码。</p><button class="wide">更新协助单</button><div id="aidMsg" class="wide form-feedback"></div></form></section></div>`);$('#updateForm').onsubmit=e=>{e.preventDefault();const place=$('#aidPlace').value.trim(),refs=$('#aidRefs').value.trim(),note=$('#aidNote').value.trim();if(!deep){alert('补充信息已保存。协助中心将继续核实。');return}const placeOK=/白潮/.test(place)&&/(712|b2)/i.test(place),refOK=/qa\s*[-－]?\s*0726\s*[-－]?\s*09/i.test(refs)&&/q7\s*[-－]?\s*b12/i.test(refs),urgentOK=/(00:?20|等待换站)/i.test(note)&&/(nightpost|夜邮|运单)/i.test(note);if(placeOK&&refOK&&urgentOK){S.ending='rescue';save();location.href='ending.html'}else{$('#aidMsg').textContent='协助中心暂时无法把这些字段关联成可执行的紧急位置。请核对：具体房间/区域、来源订单与当前运单编号，以及计划换站时间或状态。'}}}

function nightpost(){visit('night:home');const v=qs('view')||'home';if(v==='service'){shell(`<div class="np-service"><header><span>CAPABILITIES</span><h1>区域夜间供应链</h1><p>NIGHTPOST为酒店、餐饮、实验室与商业客户提供夜间冷链和定时配送。</p></header><section><div><b>Cold Chain</b><h2>冷链配送</h2><p>温控仓储、夜间交接、区域末端配送。</p></div><div><b>Hotel Operations</b><h2>酒店后勤</h2><p>布草、补给、批量物资与夜间任务。</p></div><div><b>High-value Parts</b><h2>高价值配件</h2><p>按客户字段分类、状态确认与交接。</p></div><div><b>Legacy Records</b><h2>历史客户查询</h2><p>迁移期旧客户可按合作编号和账期查询历史运单。</p><a href="nightpost-query.html">进入旧客户查询</a></div></section></div>`);return}shell(`<section class="np-hero"><div class="np-hero-copy"><span>NIGHT OPERATIONS · 24/7</span><h1>Regional logistics after hours.</h1><p>冷链、酒店后勤、样本与高价值配件的夜间运输网络。</p><div><a href="nightpost.html?view=service">服务能力</a><a href="nightpost-query.html">客户查询</a></div><dl><div><dt>Coverage</dt><dd>Coast District</dd></div><div><dt>Operations</dt><dd>24 / 7</dd></div><div><dt>Portal</dt><dd>Legacy Migration</dd></div></dl></div>${photo('cold','np-photo')}</section><section class="np-status"><div><span class="green-dot"></span><b>区域网络正常</b><small>Last update 23:21</small></div><a href="nightpost-query.html">查询历史合作记录 →</a></section>`)}
function parsePeriod(x=''){const n=norm(x);if(['202608','2026年8月','082026'].map(norm).includes(n))return'202608';if(['202607','2026年7月','072026'].map(norm).includes(n))return'202607';return''}
function nightQuery(){visit('night:query');const access=S.nightAccess,active=S.nightPeriod||(access?'202607':'');if(!access){shell(`<div class="legacy-login"><aside><span>NIGHTPOST</span><b>Legacy Partner Portal</b><p>旧客户迁移期间保留的历史合作查询入口。</p><dl><div><dt>System</dt><dd>NP Legacy / 4.2</dd></div><div><dt>Status</dt><dd>Read only</dd></div></dl></aside><section><h1>历史合作查询</h1><p>输入合作编号与结算周期。查询只返回该客户对应账期的历史运单。</p><form id="nightLogin"><label>Partner ID<input id="partner" autocomplete="off" placeholder="BTH-0000"></label><label>Billing period<input id="period" autocomplete="off" placeholder="YYYYMM"></label><button>QUERY RECORDS</button></form><div id="loginMsg"></div><small>合作编号见签约或采购资料；结算周期按 YYYYMM 填写。旧客户只可查询本人合作编号对应的历史记录。</small></section></div>`);$('#nightLogin').onsubmit=e=>{e.preventDefault();const partner=norm($('#partner').value),period=parsePeriod($('#period').value);if(partner===norm(D.nightpost.partner)&&period){S.nightAccess=true;S.nightPeriod=period;save();location.reload()}else $('#loginMsg').innerHTML='<div class="np-error">合作信息不匹配。请分别核对合作编号与账期。</div>'};return}
 const code=qs('code');if(code){const x=D.nightpost.manifest.find(m=>m.code===code&&m.period===active);if(!x){location.href='nightpost-query.html';return}visit('night:'+code);if(code==='Q7-B12'){S.deepConfirmed=true;save()}shell(`<div class="manifest-detail"><div class="np-breadcrumb"><a href="nightpost-query.html">${active} records</a> / ${x.code}</div><header><div><span>SHIPMENT RECORD</span><h1>${x.code}</h1></div><em class="${code==='Q7-B12'?'live-state':''}">${x.state}</em></header>${code==='Q7-B12'?`<div class="privacy-preview"><span>ATTACHMENT PREVIEW / REDACTED</span><div class="pixel-mask"><i></i><i></i><i></i><i></i><i></i><i></i></div><p>平台脱敏预览不可用于确认具体箱体。</p><small>文字备注残留：外箱角：黄色鸭子贴</small></div>`:''}<table><tr><th>Class</th><td>${x.class}</td><th>Route</th><td>${x.route}</td></tr><tr><th>Origin reference</th><td>${x.origin}</td><th>Receiver</th><td>${x.receiver||'—'}</td></tr><tr><th>Processing</th><td colspan="3">${x.processing||'—'}</td></tr></table>${code==='Q7-B12'?`<div class="live-manifest"><b>ORIGIN MAPPING</b><p>${x.origin} → ${x.code}</p><span>当前记录时间 ${D.timeline.now}</span><span>计划换站 ${D.timeline.transfer}</span></div><div class="leader-draft"><small>UNSENT / INTERNAL NOTE</small><b>韩译</b><p>${D.nightpost.leaderDraft}</p></div>`:''}<div class="np-record-actions"><a href="nightpost-query.html">← 返回运单列表</a>${x.origin===D.order.code?`<a href="qian-archive.html?code=${encodeURIComponent(x.origin)}">打开来源订单</a>`:''}</div></div>`);return}
 const rows=D.nightpost.manifest.filter(x=>x.period===active);shell(`<div class="manifest-page"><header><div><span>PARTNER / ${D.nightpost.partner}</span><h1>Historical records</h1></div><button id="changePeriod">Change period</button></header><div class="manifest-meta"><b>Billing period ${active}</b><span>${rows.length} records</span><span>Read only</span></div><table><thead><tr><th>Record ID</th><th>Class</th><th>Status</th><th>Route</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${x.code}</b></td><td>${x.class}</td><td>${x.state}</td><td>${x.route}</td><td><a href="nightpost-query.html?code=${x.code}">OPEN</a></td></tr>`).join('')}</tbody></table><div class="manifest-foot">客户自定义字段由合作方定义，NIGHTPOST公开站不解释字段业务含义。</div></div>`);$('#changePeriod').onclick=()=>{delete S.nightAccess;delete S.nightPeriod;save();location.reload()}}

function buildSearch(){let out=[];D.qian.forEach(x=>out.push({type:'栖岸',title:x.title,text:x.text,url:'qian.html?view='+x.id}));D.forum.forEach(x=>out.push({type:'旅友圈',title:x.title,text:x.author+' '+x.text+' '+x.comments.join(' '),url:'forum.html?id='+x.id}));D.news.forEach(x=>out.push({type:'海湾晨报',title:x.title,text:x.text+' '+(x.by||''),url:'news.html?id='+x.id}));D.menus.forEach(x=>out.push({type:x.archive?'拾味旧菜单':'拾味菜单',title:x.date+' '+x.label,text:x.items.join(' ')+' '+x.note,url:x.archive?'restaurant.html?view=archive':'restaurant.html?view=history'}));D.restaurantComments.forEach((x,i)=>out.push({type:'拾味留言',title:'食客留言 '+(i+1),text:x.replaceAll('|',' '),url:'restaurant.html?view=comments'}));D.restaurantKitchen.forEach(r=>out.push({type:'拾味旧厨房',title:r.date+' 厨房预备摘要',text:r.batch+' '+r.settlement+' '+r.note,url:'restaurant.html?view=archive'}));D.hotelReviews.forEach(r=>out.push({type:'白潮住客评价',title:r.author+' · '+r.date,text:r.text,url:'hotel.html?view=reviews'}));out.push({type:'海湾晨报附件',title:'白潮后勤外包公开附件',text:'night_vendor_202608.pdf NIGHTPOST 2026-08 后勤 外包',url:'news.html?view=attachment'},{type:'白潮酒店',title:'团体入住自助',text:'团体订单 房态 正式退房 712 QA-0726-09',url:'hotel.html?view=group'},{type:'白潮酒店',title:'隐私与网络说明',text:D.hotel.privacy+' 安全确认 设备 网关',url:'hotel.html?view=privacy'},{type:'白潮酒店',title:'夜间供应商公示',text:D.hotel.supplierPublic+' NIGHTPOST',url:'hotel.html?view=supplier'},{type:'白潮酒店',title:'历史采购附件',text:D.hotel.supplierAnnex+' BTH-2407',url:'hotel.html?view=annex'},{type:'栖岸旧订单',title:'旧订单查询',text:'订单 历史行程 签约版 QA-0726-09 DAY5 白潮',url:'qian-archive.html'},{type:'NIGHTPOST',title:'NIGHTPOST 夜间供应链',text:'夜间 冷链 高价值配件 历史合作 运单 酒店后勤',url:'nightpost.html'},{type:'拾味',title:'晚场往期菜单',text:'余味 余味席 晚场 随机菜单 往期菜单',url:'restaurant.html?view=history'},{type:'安途旅保',title:'安全确认状态',text:D.insurance.safety+' '+D.insurance.gateway+' 白潮 712',url:'insurance.html?view=safety'});return out}
function balancedHits(items){const b={};items.forEach(x=>(b[x.type]??=[]).push(x));const order=Object.keys(b),out=[];let moved=true;while(moved){moved=false;for(const k of order){if(b[k].length){out.push(b[k].shift());moved=true}}}return out}
function searchPage(){visit('search:home');const q=qs('q')||'',terms=queryTerms(q);if(q&&!S.searches.includes(q)){S.searches.unshift(q);S.searches=S.searches.slice(0,10);save()}let hits=[];if(terms.length)hits=balancedHits(buildSearch().filter(x=>{const hay=norm(x.title+' '+x.text);return terms.every(t=>hay.includes(t))}));const pg=Math.max(1,Number(qs('p')||1)),size=10,start=(pg-1)*size,items=hits.slice(start,start+size);shell(`<div class="search-results-page"><div class="search-tabs"><span class="active">全部</span><span>新闻</span><span>社区</span><span>网页</span><span>旧索引</span></div>${q?`<p class="result-count">找到约 ${hits.length} 条公开结果 · “${esc(q)}”</p>`:`<div class="search-welcome"><h1>海隅搜索</h1><p>搜索公开网页、新闻、论坛与旧索引。</p>${S.searches.length?`<div>最近搜索：${S.searches.map(x=>`<a href="search.html?q=${encodeURIComponent(x)}">${esc(x)}</a>`).join(' · ')}</div>`:''}${(S.history||[]).filter(x=>!x.u.startsWith('search.html')).length?`<div class="recent-browse"><b>最近浏览</b>${(S.history||[]).filter(x=>!x.u.startsWith('search.html')).slice(0,5).map(x=>`<a href="${x.u}">${esc(x.t)}</a>`).join('')}</div>`:''}</div>`}${q&&items.length?`<div class="serp">${items.map(h=>`<article><span class="serp-url">${esc(h.type)} · ${esc(new URL(h.url,'https://haiyu.local').pathname)}</span><a href="${h.url}"><h2>${esc(h.title)}</h2></a><p>${esc(h.text.slice(0,190))}</p></article>`).join('')}</div><div class="pagination">${pg>1?`<a href="search.html?q=${encodeURIComponent(q)}&p=${pg-1}">上一页</a>`:''}${start+size<hits.length?`<a href="search.html?q=${encodeURIComponent(q)}&p=${pg+1}">下一页</a>`:''}</div>`:q?'<div class="no-results"><h2>没有找到匹配结果</h2><p>尝试缩短词语、只输入姓氏、机构名、日期或编号的一部分。</p></div>':''}</div>`)}

function ending(){const e=S.ending;if(!e){location.href='index.html';return}const liangRead=S.visits.includes('forum:f15')&&S.visits.includes('forum:f34'),flightRead=S.visits.includes('news:n07');if(e==='rescue'){const ep=S.visits.includes('mail:window-memory')&&S.visits.includes('forum:f03');shell(`<div class="ending-screen rescue"><span>AT-AID-0820 · CASE UPDATE</span><h1>一路好天气</h1><p>白潮酒店后勤区域的失联协助已经转交当地正式渠道。原计划00:20离开的车辆没有完成换站。</p><div class="ending-message"><small>陌生号码 · 00:46</small><b>林沅</b><p>周宁？</p><p>出来了。</p><p>你别先跟我妈说细的。</p></div><p>第二天上午，共享相册出现一张新的窗户照片。</p><blockquote>外面真的晴了。</blockquote>${ep?`<hr><small>一年后</small><h2>0001.jpg</h2><p>只是家里的窗户。地平线还是有一点歪。</p>`:''}${liangRead&&flightRead?`<hr><small>公开记录更新</small><p>梁昭的旧案后来被重新列为未结失联案件。顾闻在报道里只写了一句："那天取消的航班，终于不再被当成一条无关紧要的旧新闻。"</p>`:''}<a href="index.html">回到邮箱</a></div>`);return}if(e==='expose'){shell(`<div class="ending-screen"><span>海湾晨报 · 调查</span><h1>他们没有回机场</h1><p>材料提交后的第二天，顾闻重新发布了那篇被撤下的报道。随后几家媒体开始交叉核对“提前返程”的记录，栖岸官网陆续撤下旧页面。</p><blockquote>但在材料被公开前，Q7-B12已经完成换站。林沅没有出现在后来公开的获救名单里。</blockquote><p>你让更多人看见了那条路线，只是没有来得及把她带回来。</p>${liangRead&&flightRead?`<div class="ending-message"><small>后续 · 旧案重启</small><p>梁昭的"提前返程"记录与当日取消航班被重新核对，案件重新进入失联调查。</p></div>`:''}</div>`);return}shell(`<div class="ending-screen"><span>栖岸客服 · 行程状态</span><h1>已提前返程</h1><p>你把夜邮里的编号发给了项目方。客服窗口沉默了十七分钟。</p><blockquote>临时有事，提前结束旅程。谢谢大家关心。</blockquote><p>你认识她八年。她从来不写“谢谢大家关心”。</p><div class="marketing-mail"><b>下一期栖岸青年旅居计划开放报名</b><p>愿您一路好天气。</p></div></div>`)}
function notfound(){shell(`<div class="error404"><b>404</b><h1>页面不存在</h1><p>这个页面可能已经迁移、失效或被新的版本替换。</p><a href="search.html">搜索公开索引</a><a href="index.html">返回邮箱</a></div>`)}
const routes={index,qian,'qian-archive':qianArchive,forum,hotel,restaurant,news,insurance,nightpost,'nightpost-query':nightQuery,search:searchPage,ending,'404':notfound};
(routes[page()]||notfound)();
